package com.finguard.service;import com.finguard.model.*;import java.util.*;import java.math.*;
public class ReportService {public String summary(List<Transaction> ts){var credits=BigDecimal.ZERO;var debits=BigDecimal.ZERO;var counts=new EnumMap<RiskLevel,Integer>(RiskLevel.class);for(var l:RiskLevel.values())counts.put(l,0);int flagged=0;for(var t:ts){if(t.type()==TransactionType.CREDIT)credits=credits.add(t.amount());else debits=debits.add(t.amount());counts.merge(t.riskLevel(),1,Integer::sum);if(t.riskScore()>0)flagged++;}return "Transactions: "+ts.size()+" | Credit total: "+credits+" | Debit total: "+debits+" | LOW: "+counts.get(RiskLevel.LOW)+" MEDIUM: "+counts.get(RiskLevel.MEDIUM)+" HIGH: "+counts.get(RiskLevel.HIGH)+" | Flagged for review: "+flagged;}public String stats(List<Transaction> ts){var map=new TreeMap<String,Integer>();ts.forEach(t->map.merge(t.status().name(),1,Integer::sum));return "Status counts: "+map;}}
